rules:
@media not all and (min-width: 640px) {
  .max-sm\:block { display: block; }
  .max-sm\:\!flex { display: flex !important; }
}

@media (min-width: 640px) {
  .sm\:gap-2 { gap: 0.5rem; }
  .sm\:px-3\.5 { padding-left: 0.875rem; padding-right: 0.875rem; }
  .sm\:py-2 { padding-top: 0.5rem; padding-bottom: 0.5rem; }
  .sm\:text-\[14px\] { font-size: 14px; }
}

@media (max-width: 1279px) {
  .lp-header .navbar-container { padding-left: 1rem; padding-right: 1rem; }
  .lp-header .logo-img { width: 36px; height: 36px; }
  .lp-header .logo-text { font-size: 1.25rem; }
  .lp-header .mobile-menu { width: 100%; top: 4rem; }
  .lp-header .menu-open .bar1, .lp-header .menu-open .bar2, .lp-header .menu-open .bar3 { transition: 0.3s; }
}

@keyframes lang-menu-in { 
  0% { opacity: 0; transform: translateY(-4px); }
  100% { opacity: 1; transform: none; }
}

@media (max-width: 1023px) {
  .lp-footer .footer-main { flex-direction: column; gap: 2.5rem; }
  .lp-footer .footer-columns { flex-wrap: wrap; gap: 2.5rem 3rem; }
}

@media (max-width: 640px) {
  .lp-footer .footer-section { padding: 0px 1rem; }
  .lp-footer .footer-columns { grid-template-columns: repeat(2, minmax(0px, 1fr)); display: grid; }
  .lp-footer .footer-col--contact { grid-area: 2 / span 2; max-width: none; }
  .lp-footer .footer-bottom { flex-direction: column; align-items: flex-start; }
}

@media (max-width: 1023px) {
  .lp-blog .blog-featured__inner { grid-template-columns: minmax(0px, 1fr); gap: 1.25rem; }
  .lp-blog .blog-featured__inner .blog-cover { min-height: 260px; }
  .lp-blog .blog-featured__body { padding: 0px 0.5rem 0.5rem; }
  .lp-blog .blog-grid { grid-template-columns: repeat(2, minmax(0px, 1fr)); }
}

@media (max-width: 640px) {
  .lp-blog .blog-section { padding: 4.5rem 1rem 5rem; }
  .lp-blog .blog-section--page { padding-top: calc(64px + 2.5rem); }
  .lp-blog .blog-grid { grid-template-columns: minmax(0px, 1fr); }
  .lp-blog .blog-article__cover .blog-cover { height: 240px; }
}

@keyframes hero-char-in { 
  0% { opacity: 0; filter: blur(8px); transform: translateY(0.18em); }
}

@keyframes hero-cue-bounce { 
  0%, 100% { opacity: 0.35; transform: translateY(-2px); }
  50% { opacity: 1; transform: translateY(5px); }
}

@keyframes hero-fade-up { 
  0% { opacity: 0; filter: blur(8px); transform: translateY(12px); }
  100% { opacity: 1; filter: none; transform: none; }
}

@media (prefers-reduced-motion: reduce) {
  .lp-hero .hero-fade, .lp-hero .hero-typed.is-live .hero-char { animation: auto ease 0s 1 normal none running none; }
  .lp-hero .hero-typed { transition: none; }
  .lp-hero .hero-trust__track { flex-wrap: wrap; row-gap: 1rem; width: auto; animation: auto ease 0s 1 normal none running none; }
  .lp-hero .hero-trust__track img[aria-hidden] { display: none; }
  .lp-hero .hero-scroll-cue, .lp-hero .hero-scroll-cue svg, .lp-hero .phone__body, .lp-hero .phone__shadow { animation: auto ease 0s 1 normal none running none; }
}

@media (min-width: 1024px) and (max-height: 820px) {
  .lp-hero .hero-section { padding-bottom: 3.75rem; }
  .lp-hero .hero-title-slot { margin: 1rem 0px 0.9rem; }
  .lp-hero .hero-actions { margin-top: 1.6rem; }
  .lp-hero .hero-trust { --logo-scale: .82; margin-top: 1.6rem; }
  .lp-hero .hero-trust__label { margin-bottom: 0.6rem; }
}

@media (max-width: 1023px) {
  .lp-hero .hero-section { min-height: 0px; padding-top: 8.5rem; padding-bottom: 6rem; }
  .lp-hero .hero-scroll-cue { display: none; }
  .lp-hero .hero-grid { grid-template-columns: minmax(0px, 1fr); }
  .lp-hero .hero-visual { width: 100%; }
  .lp-hero .hero-copy { max-width: 640px; }
  .lp-hero .macbook__lid { border-radius: 14px 14px 5px 5px; }
}

@media (prefers-reduced-motion: reduce) {
  .lp-features .feature-tile, .lp-features .result-chart__bar { transition: none; }
  .lp-features .orbit__pill, .lp-features .shield__ring { animation: auto ease 0s 1 normal none running none; }
}

@media (max-width: 1023px) {
  .lp-features .features-grid { grid-template-columns: repeat(2, minmax(0px, 1fr)); gap: 3rem 1.5rem; }
  .lp-features .feature-tile, .lp-features .feature-tile--wide { grid-column: span 1; }
  .lp-features .feature-tile:first-child { grid-column: span 2; }
}

@media (max-width: 640px) {
  .lp-features .features-section { padding: 4.5rem 1rem 5rem; }
  .lp-features .features-heading { margin-bottom: 2.5rem; }
  .lp-features .features-grid { grid-template-columns: minmax(0px, 1fr); }
  .lp-features .feature-tile, .lp-features .feature-tile--wide, .lp-features .feature-tile:first-child { grid-column: span 1; }
  .lp-features .feature-tile__visual { height: 270px; }
}

@media (max-width: 1023px) {
  .lp-comparison .cmp-header { flex-direction: column; align-items: flex-start; gap: 1.25rem; }
  .lp-comparison .cmp-calc { grid-template-columns: minmax(0px, 1fr); }
}

@media (max-width: 767px) {
  .lp-comparison .comparison-section { padding: 4.5rem 1rem 5rem; }
  .lp-comparison .cmp-table__head, .lp-comparison .cmp-table__row { grid-template-columns: minmax(0px, 1fr) minmax(0px, 1fr); gap: 0.75rem; padding-left: 1rem; padding-right: 1rem; }
  .lp-comparison .cmp-table__corner { display: none; }
  .lp-comparison .cmp-table__label { grid-column: span 2; font-weight: 600; }
  .lp-comparison .cmp-plan { padding: 1.1rem 0.6rem; }
  .lp-comparison .cmp-plan__desc { font-size: 0.8rem; }
  .lp-comparison .cmp-features { grid-template-columns: minmax(0px, 1fr); }
  .lp-comparison .cmp-calc { padding: 1.25rem; }
  .lp-comparison .cmp-results__row { grid-template-columns: minmax(0px, 1.2fr) repeat(3, minmax(0px, 1fr)); gap: 0.4rem; padding: 0.85rem 0.75rem; font-size: 0.85rem; }
}

@media (max-width: 1023px) {
  .lp-pricing .pricing-grid { grid-template-columns: repeat(2, minmax(0px, 1fr)); }
  .lp-pricing .pricing-side { grid-column: span 2; grid-template-columns: repeat(2, minmax(0px, 1fr)); display: grid; }
}

@media (max-width: 640px) {
  .lp-faq .faq-section { padding: 4.5rem 1rem 5rem; }
  .lp-faq .faq-item__question { padding: 1rem 1rem 1rem 1.15rem; font-size: 1rem; }
  .lp-faq .faq-item__toggle { width: 34px; height: 34px; }
  .lp-faq .faq-item__answer { padding: 0px 1.15rem; }
}
